using SixLabors.ImageSharp;using SixLabors.ImageSharp.PixelFormats;using System.Runtime.CompilerServices;namespace RaymarchingConsole;public class Printer{    static double Circle(double radius, Vector2D pos, Vector2D camPos)    {        return (pos - camPos).Length() - radius;    }    static double Sphere(double radius, Vector3D pos, Vector3D camPos)    {        return (pos - camPos).Length() - radius;    }        static double Torus(double radius, Vector3D pos, Vector3D camPos)    {        Vector2D q = new Vector2D(Circle(radius * 3, pos.XY(), camPos.XY()), pos.Z);        return q.Length() -  radius;    }    static double Plane(double size, Vector3D pos, Vector3D camPos)    {        return camPos.Y - pos.Y;    }        static void Main()    {        int screenWidth = 100;        int screenHeight = 300;        double fov = 3;                RaymarchingObj sphere1 = new RaymarchingObj(2, new Vector3D(0, -1, 0), Sphere);        RaymarchingObj sphere2 = new RaymarchingObj(1.5, new Vector3D(0, 1, 0), Sphere);                Raymarching raym = new Raymarching(screenWidth, screenHeight, (double)screenWidth / screenHeight * fov, fov);        raym.Objects.Add(sphere1);        raym.Objects.Add(sphere2);        raym.MaxIterations = 200;        raym.MinDistance = 0.1;        raym.CameraDirection = new Vector3D(1, 0, 0).Normalized();        raym.CameraPosition = new Vector3D(-7, 0, 0);                double[,] frame = new double[screenWidth, screenHeight];        using Image<Rgb24> picture = new Image<Rgb24>(screenWidth, screenHeight);                Rgb24 background = Color.DarkSlateBlue.ToPixel<Rgb24>();            frame = raym.Render();        for (int i = 0; i < screenHeight; i++)        {            for (int j = 0; j < screenWidth; j++)            {                Rgb24 pixel;                if (frame[j, i] < -1)                {                    pixel = background;                }                else                {                    byte b = (byte)(Math.Round(Math.Max(frame[j, i], 0) * 200) + 35);                    pixel = new Rgb24(b, b, b);                }                picture[j, screenHeight - 1 - i] = pixel;            }        }                string sourcePath = GetSourceFilePath();        string? projectDir = Path.GetDirectoryName(sourcePath);        string fullPath = Path.Combine(projectDir ?? string.Empty, "picture.png");        picture.SaveAsPng(fullPath);        Console.WriteLine($"Image saved to: {fullPath}");    }    static string GetSourceFilePath([CallerFilePath] string? path = null) => path ?? string.Empty;}